// Visible Session Volume Value Signal Analysis Model
// Volume-profile-at-price engine: POC + value-area expansion, breakout signals.

profRows = input(24, "Profile Rows", 10, 48, 1)
vaPct = input(70, "Value Area %", 50, 90, 5)
extendLines = input(true, "Extend POC/VA Lines")
markerSize = input(1.0, "Marker Size", 0.2, 3.0, 0.1)

// ─── Visible session range ─────────────────────────────────────
sessLen = bar_index + 1
if sessLen > 120 {
    sessLen := 120
}
if sessLen < 10 {
    sessLen := 10
}

hh = highest(high, sessLen)
ll = lowest(low, sessLen)
rng = hh - ll
if rng <= 0 {
    rng := close * 0.01
}

// ─── Bin volumes: sum volume of bars whose close falls in bin ──
binVol = array()
i = 0
while i < profRows {
    array.push(binVol, 0.0)
    i := i + 1
}

k = 0
while k < sessLen {
    cK = close[k]
    vK = volume[k]
    bIdx = floor((cK - ll) / rng * profRows)
    if bIdx < 0 {
        bIdx := 0
    }
    if bIdx > profRows - 1 {
        bIdx := profRows - 1
    }
    array.set(binVol, bIdx, array.get(binVol, bIdx) + vK)
    k := k + 1
}

totalVol = array.sum(binVol)

// ─── Point of Control: max bin volume ──────────────────────────
pocBin = 0
pocVol = array.get(binVol, 0)
i = 1
while i < profRows {
    v = array.get(binVol, i)
    if v > pocVol {
        pocVol := v
        pocBin := i
    }
    i := i + 1
}
pocPrice = ll + (pocBin + 0.5) / profRows * rng

// ─── Value Area: expand from POC until vaPct of total ──────────
vaLow = pocBin
vaHigh = pocBin
accum = pocVol
target = totalVol * vaPct / 100
guard = 0
while accum < target and guard < profRows {
    leftVal = 0 - 1.0
    if vaLow > 0 {
        leftVal := array.get(binVol, vaLow - 1)
    }
    rightVal = 0 - 1.0
    if vaHigh < profRows - 1 {
        rightVal := array.get(binVol, vaHigh + 1)
    }
    if rightVal >= leftVal and vaHigh < profRows - 1 {
        vaHigh := vaHigh + 1
        accum := accum + rightVal
    } else {
        if vaLow > 0 {
            vaLow := vaLow - 1
            accum := accum + leftVal
        }
    }
    guard := guard + 1
}
vaHighPrice = ll + (vaHigh + 1) / profRows * rng
vaLowPrice = ll + vaLow / profRows * rng

// ─── Terrain height: value concentration as price-denominated terrain ──
conc = pocVol / (totalVol + 0.000000001)
vaWidth = vaHighPrice - vaLowPrice
valueTerrain = pocPrice + (conc - 0.5) * rng * 0.4 + vaWidth * 0.25

insideVA = close >= vaLowPrice and close <= vaHighPrice
prevClose = close[1]
prevInside = prevClose >= vaLowPrice and prevClose <= vaHighPrice

// ─── Signals: price leaving value ──────────────────────────────
buySig = prevInside and close > vaHighPrice
sellSig = prevInside and close < vaLowPrice

// ─── Signal markers (2D + 3D, same pane) ───────────────────────
if buySig {
    plotshape(bar_index, low, "Buy", "triangleup", "#22cc88")
    plotshape_3d(bar_index, low, "Buy", "coneup", "#22cc88", markerSize, 1, "3d")
}
if sellSig {
    plotshape(bar_index, high, "Sell", "triangledown", "#ff4477")
    plotshape_3d(bar_index, high, "Sell", "conedown", "#ff4477", markerSize, 1, "3d")
}
if buySig or sellSig {
    label3d(bar_index, pocPrice, "POC", "#ffd43b", 1.2, 2, "3d")
}

// ─── Value zone box (2D shading, extends when requested) ───────
zoneLeft = bar_index - sessLen + 1
zoneRight = bar_index
if extendLines {
    zoneRight := bar_index + 5
}
box.new(zoneLeft, vaHighPrice, zoneRight, vaLowPrice, "#22cc88", "rgba(34,204,136,0.08)", 1, "vapbox")
text.new(bar_index, pocPrice, "POC", "#ffd43b", 1, "poctext")

// ─── 2D: same information when 3D is off ────────────────────────
plot(pocPrice, "POC", "#ffd43b", 2, "stepline")
plot(vaHighPrice, "VAH", "#22cc88", 1, "stepline")
plot(vaLowPrice, "VAL", "#ff4477", 1, "stepline")

// ─── 3D: value sits as terrain, POC as labelled rail ────────────
plot3d(valueTerrain, "Value Terrain", "surface", "#22cc88", "3d", 0)
plot3d(pocPrice, "POC", "line3d", "#ffd43b", "3d", 2)

// Fix 1: var lvl = highest(high, 20) froze at bar 0 -> plain lvl = highest(high, 20) recomputed every bar.
// Fix 2: close[-1] reads a future bar -> changed to close so breakout uses the current bar only.
// Fix 3: plotshape(true, low, "Buy", shape.triangleup, color.green) is Pine syntax -> Oak is plotshape(bar_index, price, title, style, color).
// Fix 4: plot3d(r, "RSI", "surface", "#b48cff", "3d") forces an oscillator into the price scene -> moved to pane "separate".
lvl = highest(high, 20)
r = rsi(close, 14)
buySig = close > lvl
if buySig {
    plotshape(bar_index, low, "Buy", "triangleup", "#22cc88")
}
if crossover(r, 30) {
    plotshape(bar_index, low, "OS", "triangleup", "#22cc88")
}
plot(r, "RSI", "#b48cff", 1)
plot3d(r, "RSI", "surface", "#b48cff", "separate")

baseFlow = input(100, "Base Flow PSI", 10, 300, 1)
critical_threshold = input(150, "Critical Threshold", 50, 300, 1)
spin_factor = input(0.5, "Spin Factor", 0.05, 2.0, 0.05)
ring_count = input(5, "Ring Count", 1, 10, 1)
ring_expansion_speed = input(2.0, "Ring Expansion Speed", 0.1, 5.0, 0.1)
ring_max_radius = input(10.0, "Ring Max Radius", 2.0, 30.0, 0.5)
markerSize = input(1.0, "Marker Size", 0.2, 3.0, 0.1)

flow_psi = baseFlow + (close - open) * 8.0 + (high - low) * 4.0 + (close - close[1]) * 6.0
spin_speed = flow_psi * spin_factor
overpressure_state = flow_psi > critical_threshold

var discAngle = 0.0
var lockBars = 0.0

if overpressure_state {
    lockBars := lockBars[1] + 1.0
} else {
    discAngle := discAngle[1] + spin_speed
    lockBars := 0.0
}

lockedAngle = discAngle[1]

discSize = 1.5 + flow_psi * 0.002
perim = 1.5
span = ring_max_radius - perim
off1 = lockBars * ring_expansion_speed
off2 = lockBars * ring_expansion_speed + span * 0.2
off3 = lockBars * ring_expansion_speed + span * 0.4
off4 = lockBars * ring_expansion_speed + span * 0.6
off5 = lockBars * ring_expansion_speed + span * 0.8
r1 = perim + off1 - span * floor(off1 / span)
r2 = perim + off2 - span * floor(off2 / span)
r3 = perim + off3 - span * floor(off3 / span)
r4 = perim + off4 - span * floor(off4 / span)
r5 = perim + off5 - span * floor(off5 / span)

sellSig = overpressure_state and not overpressure_state[1]
buySig = not overpressure_state and overpressure_state[1]
discTick = bar_index - floor(bar_index / 10.0) * 10.0 == 0
discShow = sellSig or buySig or discTick

if sellSig {
    plotshape(bar_index, high, "Sell", "triangledown", "#ff4477", "separate")
    model.shortEntry("OverP", 1)
}
if buySig {
    plotshape(bar_index, low, "Buy", "triangleup", "#22cc88", "separate")
    model.longEntry("Release", 1)
}

if discShow {
    plotshape_3d(bar_index, flow_psi, "ValveDisc", "torus", "#33ccff", 1.5, 0, "separate", 90, lockedAngle, 0)
}
if overpressure_state {
    plotshape_3d(bar_index, flow_psi, "Shock1", "torus", "#ff4477", r1 * 0.25 * markerSize, 1, "separate", 90, 0, 0)
}
if overpressure_state {
    plotshape_3d(bar_index, flow_psi, "Shock2", "torus", "#ff8833", r2 * 0.25 * markerSize, 2, "separate", 90, 0, 0)
}
if overpressure_state {
    plotshape_3d(bar_index, flow_psi, "Shock3", "torus", "#ffcc33", r3 * 0.25 * markerSize, 3, "separate", 90, 0, 0)
}
if overpressure_state {
    plotshape_3d(bar_index, flow_psi, "Shock4", "torus", "#ff4477", r4 * 0.25 * markerSize, 4, "separate", 90, 0, 0)
}
if overpressure_state {
    plotshape_3d(bar_index, flow_psi, "Shock5", "torus", "#ff8833", r5 * 0.25 * markerSize, 5, "separate", 90, 0, 0)
}
if sellSig {
    plotshape_3d(bar_index, flow_psi, "OverP", "conedown", "#ff4477", 1.0 * markerSize, 6, "separate", 0, 0, 0)
}
if buySig {
    plotshape_3d(bar_index, flow_psi, "Normal", "coneup", "#22cc88", 1.0 * markerSize, 6, "separate", 0, 0, 0)
}
if overpressure_state {
    label3d(bar_index, flow_psi + 12.0, "OVERPRESSURE", "#ff4477", 2, 7, "separate")
}

plot(flow_psi, "Flow PSI", "#22aaff", 2, "separate")
plot(spin_speed, "Spin Speed", "#ffcc33", 1, "separate")
hline(critical_threshold, "#ff4477", "separate")
plot3d(flow_psi, "Flow PSI 3D", "ribbon", "#22aaff", "separate")
plot3d(spin_speed, "Spin Speed 3D", "trail", "#ffcc33", "separate", 1)
